# Alum on and off with the best parameter set (member 46 of stage j, new AEME dev and GLM-AED): GLM nutrient budgets, and the outflow from AEME::aeme_to_inflow()
# against the measured Ohau Channel flow and lab results.
# Needs calibration/historical/out_budget_m46 and out_budget_m46_noalum (run_hist.R with HIST_KEEP=1, HIST_N=1; the no-alum run uses HIST_BASE=calibration/alum/stream/base_Q50_noalum.rds).
suppressMessages({library(AEME); library(dplyr); library(tidyr); library(ggplot2); library(readr); library(lubridate)})
out <- "website/images/budget"; dat <- "website/data/budget"; dir.create(out, recursive = TRUE, showWarnings = FALSE); dir.create(dat, recursive = TRUE, showWarnings = FALSE)
RUN <- c(alum = "With observed alum", none = "No alum"); COL <- c("With observed alum" = "steelblue4", "No alum" = "firebrick"); dirs <- c(alum = "calibration/historical/out_budget_m46", none = "calibration/historical/out_budget_m46_noalum")
A <- lapply(dirs, \(d) readRDS(file.path(d, "aeme_46.rds"))); MEM <- lapply(dirs, \(d) readRDS(file.path(d, "member_46.rds"))$daily)
# ---- budgets ----
B <- list(alum = readRDS(file.path(dirs[["alum"]], "glm_budget.rds")), none = AEME:::diag_glm_budget(A$none, element = c("N", "P", "C"), period = "all", include_spin_up = FALSE)); saveRDS(B$none, file.path(dirs[["none"]], "glm_budget.rds"))
for (e in c("P", "N")) ggsave(file.path(out, paste0("glm_budget_", e, "_noalum.png")), AEME:::plot_glm_budget(B$none, element = e, units = "kg_yr"), width = 8, height = 7, dpi = 140, bg = "white")
cl <- bind_rows(lapply(names(B), \(k) B[[k]]$closure |> mutate(run = RUN[[k]]))) |> filter(element %in% c("N", "P")) |> select(element, term, run, kg_yr) |> pivot_wider(names_from = run, values_from = kg_yr) |> mutate(difference = `With observed alum` - `No alum`)
write_csv(cl |> mutate(across(where(is.numeric), \(x) signif(x, 4))), file.path(dat, "budget_closure_pair.csv")); cat("Closure (kg/yr):\n"); print(as.data.frame(cl |> mutate(across(where(is.numeric), \(x) round(x)))), row.names = FALSE)
fx <- bind_rows(lapply(names(B), \(k) B[[k]]$fluxes |> mutate(run = RUN[[k]]))) |> filter(element %in% c("N", "P")) |> select(element, process, run, kg_yr) |> pivot_wider(names_from = run, values_from = kg_yr) |> mutate(difference = `With observed alum` - `No alum`)
write_csv(fx |> mutate(across(where(is.numeric), \(x) signif(x, 4))), file.path(dat, "budget_fluxes_pair.csv")); cat("\nFluxes (kg/yr):\n"); print(as.data.frame(fx |> mutate(across(where(is.numeric), \(x) round(x)))), row.names = FALSE)
tl <- c(inflow = "Inflow", outflow = "Outflow", sediment = "Sediment (net)", atmosphere = "Atmosphere (net)", d_storage = "Change in storage", residual = "Not explained")
g1 <- cl |> filter(term %in% names(tl)) |> pivot_longer(c(`With observed alum`, `No alum`), names_to = "run", values_to = "kg") |> mutate(kg = kg / 1000, term = factor(tl[term], tl), element = factor(element, c("P", "N"), c("Phosphorus (t P/yr)", "Nitrogen (t N/yr)")), run = factor(run, RUN))
ggsave(file.path(out, "budget_pair_closure.png"), ggplot(g1, aes(term, kg, fill = run)) + geom_hline(yintercept = 0, colour = "grey60") + geom_col(position = position_dodge(0.8), width = 0.75) + facet_wrap(~element, scales = "free_y") + scale_fill_manual(values = COL) + labs(x = NULL, y = "Mean flux, t per year", fill = NULL, subtitle = "Boundary terms of the whole-lake budget, 2005 to 2022; sediment and atmosphere are net (positive: into the lake).") + theme_minimal(base_size = 10) + theme(legend.position = "bottom", axis.text.x = element_text(angle = 30, hjust = 1), plot.subtitle = element_text(size = 8)), width = 11, height = 5, dpi = 130, bg = "white")
g2 <- fx |> filter(!process %in% c("Resuspension", "Adsorbed P resuspension", "Sediment DOP", "Sediment DON", "Sediment DOC", "Sediment release", "Adsorbed P settling", "Photosynthesis", "Respiration", "Settling", "Phytoplankton settling")) |> bind_rows(fx |> filter(process %in% c("Settling", "Phytoplankton settling")) |> group_by(element) |> summarise(process = "Settling (all)", across(c(`With observed alum`, `No alum`), \(x) sum(abs(x))), difference = `With observed alum` - `No alum`, .groups = "drop")) |>
  pivot_longer(c(`With observed alum`, `No alum`), names_to = "run", values_to = "kg") |> mutate(kg = abs(kg) / 1000, element = factor(element, c("P", "N"), c("Phosphorus (t P/yr)", "Nitrogen (t N/yr)")), run = factor(run, RUN))
ggsave(file.path(out, "budget_pair_fluxes.png"), ggplot(g2, aes(reorder(process, kg), kg, fill = run)) + geom_col(position = position_dodge(0.8), width = 0.75) + coord_flip() + facet_wrap(~element, scales = "free") + scale_fill_manual(values = COL) + labs(x = NULL, y = "Mean flux magnitude, t per year", fill = NULL, subtitle = "Internal process fluxes (absolute size); the settling bar adds the particulate and phytoplankton settling.") + theme_minimal(base_size = 10) + theme(legend.position = "bottom", plot.subtitle = element_text(size = 8)), width = 11, height = 5.5, dpi = 130, bg = "white")
# ---- outflow ----
DOPR <- 0.15 * 30.974 / 1000; DONR <- 9 * 14.0067 / 1000
X <- bind_rows(lapply(names(A), \(k) AEME::aeme_to_inflow(A[[k]]) |> filter(Date >= "2005-07-01", Date <= "2022-06-29") |> transmute(run = RUN[[k]], Date, flow = HYD_flow, TP = PHS_tp + DOPR, DRP = PHS_frp, TN = NIT_tn + DONR, `NH4-N` = NIT_amm, NNN = NIT_nit, `Water Temp` = HYD_temp)))
fl <- targets::tar_read(rotorua_flow_data); vc <- grep("^Value", names(fl), value = TRUE)[1]
mf <- fl |> transmute(Date = as.Date(`Timestamp (UTC+12:00)`), q = .data[[vc]]) |> filter(is.finite(q)) |> group_by(Date) |> summarise(q = mean(q), n = n(), .groups = "drop") |> filter(n >= 12) |> mutate(obs = q * 86400)
fs <- X |> select(run, Date, sim = flow) |> inner_join(mf |> select(Date, obs), by = "Date") |> group_by(run) |> summarise(n = n(), obs_mean_m3s = mean(obs) / 86400, sim_mean_m3s = mean(sim) / 86400, bias_pct = 100 * (mean(sim) / mean(obs) - 1), r = cor(sim, obs), nse = 1 - sum((sim - obs)^2) / sum((obs - mean(obs))^2), .groups = "drop"); write_csv(fs |> mutate(across(where(is.numeric), \(x) signif(x, 3))), file.path(dat, "outflow_flow_pair.csv")); cat("\nFlow (2010-10 on):\n"); print(as.data.frame(fs), row.names = FALSE)
cat("max |difference| in modelled outflow between the runs (m3/d):", max(abs((X |> filter(run == RUN[["alum"]]))$flow - (X |> filter(run == RUN[["none"]]))$flow)), "\n")
per <- \(d) as.vector(ifelse(d < "2011-01-01", "2005 to 2010", "2011 to 2022"))
wq <- targets::tar_read(ohau_wq_data) |> transmute(Date = as.Date(Timestamp), variable, obs = value) |> filter(Date >= "2005-07-01", Date <= "2022-06-29", variable %in% c("TP", "DRP", "TN", "NH4-N", "NNN", "Water Temp")) |> group_by(Date, variable) |> summarise(obs = mean(obs), .groups = "drop")
L <- X |> select(-flow) |> pivot_longer(-c(run, Date), names_to = "variable", values_to = "sim")
J <- inner_join(L, wq, by = c("Date", "variable")) |> filter(!(variable == "TN" & Date < "2009-01-01")) |> mutate(period = per(Date))
sc <- function(d) tibble(n = nrow(d), obs_median = median(d$obs), sim_median = median(d$sim), bias_pct = 100 * (mean(d$sim) / mean(d$obs) - 1), r = cor(d$sim, d$obs), rmse = sqrt(mean((d$sim - d$obs)^2)))
st <- bind_rows(J |> group_by(variable, run) |> group_modify(~sc(.x)) |> ungroup() |> mutate(period = "All"), J |> group_by(variable, run, period) |> group_modify(~sc(.x)) |> ungroup()) |> mutate(across(where(is.numeric), \(v) signif(v, 3))) |> arrange(variable, period, run)
write_csv(st, file.path(dat, "outflow_conc_pair.csv")); cat("\nOutflow concentrations against the Ohau lab samples:\n"); print(as.data.frame(st |> filter(period != "All")), row.names = FALSE)
vl <- c(TP = "Total P (g/m3)", DRP = "DRP (g/m3)", TN = "Total N (g/m3)", `NH4-N` = "NH4-N (g/m3)", NNN = "Nitrate+nitrite N (g/m3)", `Water Temp` = "Water temperature (C)")
Lp <- L |> filter(variable != "Water Temp") |> mutate(lab = factor(vl[variable], vl), run = factor(run, RUN)); Op <- wq |> filter(variable != "Water Temp") |> mutate(lab = factor(vl[variable], vl))
ggsave(file.path(out, "outflow_pair_conc.png"), ggplot(Lp, aes(Date, sim, colour = run)) + geom_vline(xintercept = as.Date(c("2006-06-15", "2010-01-14")), linetype = 2, colour = "grey50") + geom_line(linewidth = 0.35) + geom_point(data = Op, aes(Date, obs), colour = "black", size = 0.7, inherit.aes = FALSE) + facet_wrap(~lab, ncol = 1, scales = "free_y") + scale_colour_manual(values = COL) +
  labs(x = NULL, y = NULL, colour = NULL, subtitle = "Daily flow-weighted outflow concentration from the GLM mass balance (lines) and Ohau Channel lab samples (points). TP and TN include the refractory offsets.") + theme_minimal(base_size = 10) + theme(legend.position = "bottom", plot.subtitle = element_text(size = 8)), width = 10, height = 12, dpi = 130, bg = "white")
# annual export (kg/yr): model flow x concentration, and a rough observed estimate from the lab samples and same-day measured flow
ld <- X |> mutate(yr = year(Date)) |> group_by(run, yr) |> summarise(TP = sum(flow * TP) / 1000, TN = sum(flow * TN) / 1000, .groups = "drop") |> pivot_longer(c(TP, TN), names_to = "variable", values_to = "kg")
lo <- wq |> filter(variable %in% c("TP", "TN")) |> inner_join(mf |> select(Date, obs_flow = obs), by = "Date") |> mutate(yr = year(Date), load = obs * obs_flow / 1000 * 365) |> group_by(variable, yr) |> filter(n() >= 8) |> summarise(kg = mean(load), n = n(), .groups = "drop") |> mutate(run = "Observed estimate")
LD <- bind_rows(ld, lo |> select(run, yr, variable, kg)) |> filter(yr >= 2011, yr <= 2021); write_csv(LD |> mutate(kg = signif(kg, 4)), file.path(dat, "outflow_loads_pair.csv"))
ls <- LD |> group_by(variable, run) |> summarise(mean_t_yr = mean(kg) / 1000, .groups = "drop"); cat("\nMean annual export 2011 to 2021 (t/yr):\n"); print(as.data.frame(ls |> mutate(mean_t_yr = round(mean_t_yr, 2))), row.names = FALSE)
CC <- c(COL, "Observed estimate" = "black")
ggsave(file.path(out, "outflow_pair_loads.png"), ggplot(LD |> mutate(variable = factor(variable, c("TP", "TN"), c("Total P export (t P/yr)", "Total N export (t N/yr)")), run = factor(run, c(RUN, "Observed estimate")), kg = kg / 1000), aes(yr, kg, colour = run)) + geom_line(linewidth = 0.6) + geom_point(size = 1.4) + facet_wrap(~variable, scales = "free_y") + scale_colour_manual(values = CC) + labs(x = NULL, y = NULL, colour = NULL, subtitle = "Model: daily flow times concentration, summed. Observed estimate: mean of (lab sample x same-day measured flow) x 365, years with at least 8 samples.") + theme_minimal(base_size = 10) + theme(legend.position = "bottom", plot.subtitle = element_text(size = 8)), width = 10, height = 4.5, dpi = 130, bg = "white")
cat("done\n")
